<template>
  <AccountPageShell class="care-page" active-page="care" title="My care" description="Appointments and care requests you have arranged through LVYV." :ready="ready">
    <div class="care-tabs"><button v-for="tab in tabs" :key="tab.value" type="button" :class="{active: activeTab === tab.value}" @click="activeTab = tab.value">{{ tab.label }}</button></div>
    <div v-if="loading" class="state" role="status">Loading your care...</div><div v-else-if="error" class="state error" role="alert">{{ error }} <button type="button" @click="load">Try again</button></div><div v-else-if="!appointments.length" class="state empty"><strong>No care requests yet</strong><span>When you request a planned service, it will appear here.</span><NuxtLink to="/health/services">Explore health services</NuxtLink></div><div v-else class="care-list"><article v-for="item in appointments" :key="item.appointmentNo" class="care-card"><img :src="item.serviceCode?.toLowerCase().includes('dental')?'/images/health/design/care-dental.webp':'/images/health/design/care-checkup.webp'" alt="" class="care-image"><div class="care-card-content"><h2>{{ item.serviceTitle }}</h2><p>{{ appointmentTime(item) }} · {{ item.cityName }}</p><span class="status" :class="item.status.toLowerCase()">{{ labels[item.status] || item.status }}</span></div><NuxtLink :to="`/health/appointments/${item.appointmentNo}`">View details</NuxtLink></article></div>
    <div v-if="!loading && !error && (page > 1 || appointments.length === 20)" class="care-pagination"><button type="button" :disabled="page === 1" @click="page--">Previous</button><span>{{ page }}</span><button type="button" :disabled="appointments.length < 20" @click="page++">Next</button></div>
  </AccountPageShell>
</template>
<script setup lang="ts">
import AccountPageShell from '~/components/profile/AccountPageShell.vue'
const { ready, initializeAccount } = useAccountPage('/care'); const health = useHealthCare(); const activeTab = ref('UPCOMING'); const loading = ref(true); const error = ref(''); const appointments = ref<import('~/composables/useHealthCare').HealthAppointment[]>([])
const tabs = [{ value: 'UPCOMING', label: 'Upcoming' }, { value: 'PAST', label: 'Past' }, { value: 'REQUESTS', label: 'Requests' }]; const labels: Record<string, string> = { REQUESTED: 'Requested', PROVIDER_CONFIRMING: 'Provider confirming', PAYMENT_REQUIRED: 'Payment required', PAID: 'Confirmed', COMPLETED: 'Completed', CANCELLED: 'Cancelled', RESCHEDULE_REQUESTED: 'Reschedule requested', CANCEL_REQUESTED: 'Cancellation requested', PROVIDER_REJECTED: 'Provider unavailable', NO_SHOW: 'No-show', EXPIRED: 'Expired' }
let loadSequence = 0
const page = ref(1)
const load = async () => { const sequence = ++loadSequence; loading.value = true; error.value = ''; try { const result = await health.listAppointments(activeTab.value, page.value); if (sequence === loadSequence) appointments.value = result } catch (e) { if (sequence === loadSequence) error.value = e instanceof Error ? e.message : 'Unable to load your care.' } finally { if (sequence === loadSequence) loading.value = false } }
const appointmentTime = (item: import('~/composables/useHealthCare').HealthAppointment) => item.confirmedStartUtc
  ? new Intl.DateTimeFormat('en-US', { timeZone: item.destinationTimezone, dateStyle: 'medium', timeStyle: 'short' }).format(new Date(item.confirmedStartUtc)) + ' (China time)'
  : `${item.preferredDate} · ${item.preferredTimeWindow}`
watch(activeTab, () => { page.value = 1; load() }); watch(page, load); onMounted(async () => { if (await initializeAccount()) await load() }); useLvyvSeo({ title: 'My Care | LVYV Care', description: 'Manage your LVYV Care appointments and requests.', path: '/care', noindex: true })
</script>
<style scoped>
.care-page{--font-ui:Inter,sans-serif;font-weight:400}
.care-page{background:#f5f6f3;font-family:Inter,sans-serif}.care-page :deep(.account-heading h1){font-family:Philosopher,Georgia,serif}.care-tabs{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));max-width:704px;margin-bottom:30px;background:#fff;border-radius:5px 0 0 5px;overflow:hidden}.care-tabs button{border:0;background:#fff;padding:8px 16px;min-height:32px;color:#0008;font:400 14px/20px Inter,sans-serif;cursor:pointer}.care-tabs button.active{color:#fff;background:#203d33}.care-list{display:grid;gap:20px}.care-card{background:#fff;border-radius:12px;min-height:170px;padding:30px 20px;display:grid;grid-template-columns:128px minmax(0,1fr) auto;align-items:start;gap:20px;box-shadow:0 4px 8px #1122110d}.care-image{width:128px;height:112px;object-fit:cover;border-radius:4px}.care-card-content{min-width:0}.care-card h2{font:700 16px/24px Inter,sans-serif;margin:0 0 4px;color:#2e473d}.care-card p{margin:0;color:#242424;font-size:14px;line-height:20px}.care-card a{align-self:end;background:#203d33;color:#fff;font:500 12px/20px Inter,sans-serif;border-radius:3px;padding:6px 16px;text-decoration:none;white-space:nowrap}.status{display:inline-block;margin-top:36px;min-width:110px;text-align:center;font:400 12px/20px Inter,sans-serif;border:1px solid #698e4e;border-radius:26px;background:#edf9e1;color:#2a573f;padding:0 8px;letter-spacing:0}.status.requested,.status.provider_confirming,.status.payment_required,.status.reschedule_requested,.status.cancel_requested{border-color:#ff9915;color:#ff9915;background:#fff8ee}.status.cancelled,.status.provider_rejected,.status.no_show,.status.expired{color:#a43d32;border-color:#b36b63;background:#fff4f2}.state{padding:48px 0;color:#677489;display:grid;gap:10px;font-size:14px}.state.empty{min-height:280px;align-content:center;justify-items:center;text-align:center;box-sizing:border-box}.state strong{color:#203d33}.state a{color:#105446}.state button{border:0;background:none;color:#105446;text-decoration:underline;cursor:pointer}.error{color:#a43d32}.care-pagination{display:flex;justify-content:flex-end;align-items:center;gap:16px;margin-top:24px}.care-pagination button{border:0;background:none;color:#105446;cursor:pointer}.care-pagination button:disabled{opacity:.4;cursor:default}
@media(max-width:600px){.care-card{grid-template-columns:80px minmax(0,1fr);padding:20px 16px;gap:14px}.care-image{width:80px;height:90px}.care-card a{grid-column:2;justify-self:start}.status{margin-top:14px;min-width:0;max-width:100%;font-size:11px}.care-tabs button{padding:8px;font-size:13px}.care-card h2{font-size:15px}.care-card p{font-size:12px}}
</style>
